import { test, expect } from '@playwright/test';

/**
 * Generated by DOMONO Module 3 (Playwright Script Generator)
 * Story: HELP-142 — Real-time email alert on ticket reassignment
 * Locators sourced from Module 2 (DOM & Environment Scanner) output.
 */

test.describe('HELP-142: Ticket reassignment notifications', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://helpdesk.example.com/tickets/4821');
  });

  test('HELP-142-TC01: Agent receives email on ticket reassignment', async ({ page }) => {
    await page.getByTestId('reassign-agent-select').selectOption({ label: 'Agent A' });
    await page.getByRole('button', { name: 'Confirm Reassignment' }).click();

    await expect(page.getByText('Ticket status: Reassigned')).toBeVisible();
    await expect(page.getByTestId('notification-toast')).toContainText('Email sent to Agent A');
  });

  test('HELP-142-TC02: No email sent when reassigned to self', async ({ page }) => {
    await page.getByTestId('reassign-agent-select').selectOption({ label: 'Current User' });
    await page.getByRole('button', { name: 'Confirm Reassignment' }).click();

    await expect(page.getByTestId('notification-toast')).toHaveCount(0);
  });
});
